/*
 * gpu/gpu-tex-fill10p-cmdprobe - GPUSTAT bit 26 (ready for a command) read N cycles after gpu-tex-fill10p's 1st store of FC00h to GP0/GPUREAD 1F801810h (32-bit), N stepped across
 * the window where two models part. Generated by tools/mkprobe.js on 2026-11-12; docs/DISCRIMINATE.md section 5.
 *
 * WHY. tools/discriminate.js --inside=gpu-tex-fill10p --set=W=208,GAP=32,J=1, v327 (scratch/_cores/v0.377.327/psx.js) against v330 (scratch/_cores/v0.377.330/psx.js):
 * GP0(25h) runs, the GPU busy 7232.00 cycles after it, FIFO 0 queued: v327 7,232, v330 7,261 cycles after the 1st store of FC00h to GP0/GPUREAD 1F801810h (32-bit).
 * gpu-tex-fill10p prints nothing that moves with it. This probe reads it: on v327 the bit sets 7,232 cycles after the store (the command's end), on v330 it sets 7,261 cycles after the store (the command's end).
 *
 * WHAT IT DOES. It runs gpu-tex-fill10p's own program (preamble.inc: hwtests/gpu-tex-fill10p/main.cpp, copied verbatim but for its PARAMS marker (PARM -> PARQ, one block an exe) and its knobs W=208 GAP=32 J=1) from
 * its first line to its K-th store of FC00h to GP0/GPUREAD 1F801810h (32-bit) - the full preamble, which sets the timing phase. There the probe makes that store
 * itself, then B turns of a three-instruction loop and n nops, then ONE read of GPUSTAT. The loop and sled run cached: one pass
 * through them without the store warms the I-cache before the program's 1st store of 0h to GP0/GPUREAD 1F801810h (32-bit), 4 I/O stores ahead of the event (tools/mkprobe.js put it where the event lands as in gpu-tex-fill10p: PREDICTED.txt). Then the GPU is let finish (every wait bounded), the program's .data
 * and .bss are copied back to what they were at the start, the GPU's texture cache invalidated (GP0(01h): the cache is not RAM, and a run must meet it cold as the original's one run did), and the program runs again from its first line: one read a run,
 * n = 0..NN-1, T tries an n, tries outermost. What the program prints on the way is formatted into a buffer and thrown away, so
 * the run ends at this probe's own "Done.". Its other waits are its own; a run that never makes the store ends at its 1,200th
 * VSync or its return, and the probe stops there and says so.
 *
 * THE PARAMS BLOCK (tools/paramexe.js): B loop turns; NN how many n (at most 256); T tries an n; K which store of FC00h to GP0/GPUREAD 1F801810h (32-bit) (1st in
 * gpu-tex-fill10p); D0 the cycles from the store to the read at n = 0, measured on v327 with tools/insidehook.js (the rows'
 * N = D0 + n). D0 is the emulator's number: the "delay" line times the same loop and read with Timer 2, so a console whose
 * line differs from PREDICTED.txt's has its N shifted by that much.
 *
 * READ IT LIKE THIS. A row: N, n, then how many of the T tries read bit 26 set. PREDICTED.txt has both candidates' rows
 * and the N they differ at; the console's rows side with one, or with neither.
 *
 * ON THIS CORE (`node hwtests/run.js gpu-tex-fill10p-cmdprobe --frames=908 --quiet=908`): PREDICTED.txt.
 */
#include <common.h>
#include <psxapi.h>
#include <io.h>

#include <stdio.h>
#include <stdarg.h>

#define PZ_TAG(a, b, c, d) ((uint32_t)(a) | ((uint32_t)(b) << 8) | ((uint32_t)(c) << 16) | ((uint32_t)(d) << 24))
__attribute__((used)) static volatile const uint32_t PZ_PARAMS[16] = {
    0x4D524150u /* 'PARM' */, 5,
    PZ_TAG('B', 0, 0, 0), 2369,
    PZ_TAG('N', 'N', 0, 0), 173,
    PZ_TAG('T', 0, 0, 0), 8,
    PZ_TAG('K', 0, 0, 0), 1,
    PZ_TAG('D', '0', 0, 0), 7117,
};
#define PZ_NMAX 256

/* setjmp / longjmp, ours (the SDK has none): the callee-saved registers, SP, FP, RA, GP */
extern "C" int pz_setjmp(uint32_t* jb) __attribute__((returns_twice));
extern "C" void pz_longjmp(uint32_t* jb) __attribute__((noreturn));
__asm__(
    ".text\n.set push\n.set noreorder\n"
    ".globl pz_setjmp\n.type pz_setjmp, @function\npz_setjmp:\n"
    " sw $s0, 0($a0)\n sw $s1, 4($a0)\n sw $s2, 8($a0)\n sw $s3, 12($a0)\n sw $s4, 16($a0)\n sw $s5, 20($a0)\n"
    " sw $s6, 24($a0)\n sw $s7, 28($a0)\n sw $sp, 32($a0)\n sw $fp, 36($a0)\n sw $ra, 40($a0)\n sw $gp, 44($a0)\n"
    " jr $ra\n move $v0, $zero\n"
    ".globl pz_longjmp\n.type pz_longjmp, @function\npz_longjmp:\n"
    " lw $s0, 0($a0)\n lw $s1, 4($a0)\n lw $s2, 8($a0)\n lw $s3, 12($a0)\n lw $s4, 16($a0)\n lw $s5, 20($a0)\n"
    " lw $s6, 24($a0)\n lw $s7, 28($a0)\n lw $sp, 32($a0)\n lw $fp, 36($a0)\n lw $ra, 40($a0)\n lw $gp, 44($a0)\n"
    " jr $ra\n li $v0, 1\n"
    ".set pop\n");

/* The probe's own state, outside the program's image (64 KB above its end, below 80125000h where the runner's own begin):
 * copying .data / .bss back must not touch it */
extern "C" char _fdata[], _end[];
struct PZ { uint32_t jb[12]; uint32_t hits, whits, k, n, b, fired, bit, vs, t, i, len; uint16_t set[PZ_NMAX], tries[PZ_NMAX]; char line[512]; uint32_t snap[1]; };
static inline PZ* pz() { return (PZ*)((((uint32_t)_end) + 0x10000u + 63u) & ~63u); }

/* The store, B turns, n nops, one read. warm: the same path without the store (the loop and sled into the I-cache). */
static uint32_t __attribute__((noinline, aligned(64))) pz_shot(uint32_t v, uint32_t b, uint32_t n, uint32_t warm) {
    uint32_t r;
    __asm__ volatile(
        ".set push\n.set noreorder\n"
        " lui $t9, 0x1f80\n"
        " la $t6, 9f\n sll $t7, %[n], 2\n subu $t6, $t6, $t7\n"
        " move $t5, %[b]\n"
        " bnez %[w], 1f\n nop\n"
        " sw %[v], 0x1810($t9)\n"
        "1: beqz $t5, 3f\n nop\n"
        "2: addiu $t5, $t5, -1\n bnez $t5, 2b\n nop\n"
        "3: jr $t6\n nop\n"
        " .rept 256\n nop\n .endr\n"
        "9: lw %[r], 0x1814($t9)\n nop\n"
        ".set pop\n"
        : [r] "=&r"(r) : [v] "r"(v), [b] "r"(b), [n] "r"(n), [w] "r"(warm) : "t5", "t6", "t7", "t9", "memory");
    return r;
}

static void __attribute__((noinline, noreturn)) pz_fire(uint32_t v) {
    PZ* p = pz();
    /* warmed earlier, before the 1st store of 0h to GP0/GPUREAD 1F801810h (32-bit) */
    const uint32_t r = pz_shot(v, p->b, p->n, 0);
    p->bit = (r >> 26) & 1u; p->fired = 1;
    /* the command finished (GPUSTAT bits 26 and 28), or its FIFO reset (GP1(01h)) if it never does */
    for (int j = 0; j < 2000000 && (read32(0x1F801814u) & 0x14000000u) != 0x14000000u; j++) {}
    if ((read32(0x1F801814u) & 0x04000000u) == 0) write32(0x1F801814u, 0x01000000u);
    pz_longjmp(p->jb);
}

/* The original's stores: its K-th store of FC00h to 1F801810h is the probe's */
static inline __attribute__((always_inline)) void pz_store32(uint32_t a, uint32_t v) {
    if (a == 0x1F801810u && v == (uint32_t)0x0u) { PZ* p = pz(); if (++p->whits == 1u) (void)pz_shot(0, 1, PZ_NMAX - 1, 1); }   /* the warm pass, before the 1st store of 0h to GP0/GPUREAD 1F801810h (32-bit) */
    if (a == 0x1F801810u && v == (uint32_t)0xFC00u) { PZ* p = pz(); if (++p->hits == p->k) pz_fire(v); }
    write32(a, v);
}
static void pz_printf(const char* f, ...) { va_list ap; va_start(ap, f); vsnprintf(pz()->line, sizeof pz()->line, f, ap); va_end(ap); }
static int pz_vsync(int m) { PZ* p = pz(); if (++p->vs > 1200) { p->fired = 2; pz_longjmp(p->jb); } return VSync(m); }

#define write32(a, v) pz_store32((a), (v))
#define printf pz_printf
#define VSync pz_vsync
#define main pz_orig_main
#include "preamble.inc"
#undef main
#undef VSync
#undef printf
#undef write32

int main() {
    PZ* p = pz();
    p->len = ((uint32_t)(_end - _fdata) + 3u) / 4u;
    for (int j = 0; j < PZ_NMAX; j++) { p->set[j] = 0; p->tries[j] = 0; }   /* RAM above the image holds whatever was there */
    { const uint32_t* d = (const uint32_t*)_fdata; for (uint32_t j = 0; j < p->len; j++) p->snap[j] = d[j]; }
    printf("\ngpu/gpu-tex-fill10p-cmdprobe\n");
    printf("gpu-tex-fill10p's program to its 1st store of FC00h to GP0/GPUREAD 1F801810h (32-bit), then B loop turns and n nops after that store and ONE GPUSTAT read:\n");
    printf("bit 26 (ready for a command) at N = D0 + n cycles after it, one read a run of the program. No assertions.\n\n");
    const uint32_t B = PZ_PARAMS[3], NN = PZ_PARAMS[5], T = PZ_PARAMS[7], K = PZ_PARAMS[9], D0 = PZ_PARAMS[11];
    printf("params B=%u NN=%u T=%u K=%u D0=%u\n", (unsigned)B, (unsigned)NN, (unsigned)T, (unsigned)K, (unsigned)D0);
    uint32_t fail = 0;
    if (NN < 1 || NN > PZ_NMAX || T < 1 || T > 64 || K < 1) { printf("params out of range (NN 1..%d, T 1..64, K 1 up)\n", PZ_NMAX); goto done; }
    if ((uint32_t)&p->snap[p->len] >= 0x80125000u) { printf("the program is too large for the probe's state below 80125000h\n"); goto done; }
    {   /* the delay itself on Timer 2 (the system clock: the runner leaves it so): B turns, n = 0, the read; no store */
        uint32_t best = 0xFFFFFFFFu;
        for (int j = 0; j < 4; j++) { const uint16_t a = read16(0x1F801120u); (void)pz_shot(0, B, 0, 1); const uint16_t c = read16(0x1F801120u); if ((uint16_t)(c - a) < best) best = (uint16_t)(c - a); }
        printf("the delay at n = 0 without the store, Timer 2: %u cycles (the call and a timer read in it)\n\n", (unsigned)best);
    }
    for (p->t = 0; p->t < T; p->t++)
        for (p->i = 0; p->i < NN; p->i++) {
            { uint32_t* d = (uint32_t*)_fdata; for (uint32_t j = 0; j < p->len; j++) d[j] = p->snap[j]; }
            for (int j = 0; j < 2000000 && (read32(0x1F801814u) & 0x04000000u) == 0; j++) {}   /* ready (bounded) */
            write32(0x1F801810u, 0x01000000u);   /* GP0(01h): the texture cache invalidated */
            p->hits = 0; p->whits = 0; p->k = K; p->n = p->i; p->b = B; p->fired = 0; p->vs = 0;
            if (!pz_setjmp(p->jb)) { pz_orig_main(); p->fired = 3; }
            if (p->fired != 1) { fail = p->fired; goto rows; }
            p->set[p->i] += (uint16_t)p->bit; p->tries[p->i]++;
        }
rows:
    if (fail) printf("STOPPED at try %u, n %u: %s\n\n", (unsigned)p->t, (unsigned)p->i, fail == 2 ? "the program waited 1,200 VSyncs without the store" : "the program ended without the store");
    printf("GPUSTAT bit 26 (ready for a command), N cycles after the store: tries that read it set\n");
    for (uint32_t i = 0; i < NN; i++) printf("  N %u (n %u): %u of %u\n", (unsigned)(D0 + i), (unsigned)i, (unsigned)p->set[i], (unsigned)p->tries[i]);
done:
    printf("\ngpu/gpu-tex-fill10p-cmdprobe: Done.\n");
    for (;;) {}
}
